// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        c.Initialized();

        bool ok;
        address logAddr = actor;

        vm.prank(actor);
        try c.SetLogFile(logAddr) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
